module max4 ( a, b, c, d, res, addr );

  input [0:0] a, b, c, d;
  output [0:0] res;
  output [1:0] addr;

  wire [0:0] A = a;
  wire [0:0] B = b;
  wire [0:0] C = c;
  wire [0:0] D = d;

  wire AB, AC, AD, BC, BD, CD;

  comp( A, B, AB );
  comp( A, C, AC );
  comp( A, D, AD );
  comp( B, C, BC );
  comp( B, D, BD );
  comp( C, D, CD );

  assign addr = AB ?  (CD ? (AC ? 2'b00 : 2'b10) : (AD ? 2'b00 : 2'b11))  :  (CD ? (BC ? 2'b01 : 2'b10) : (BD ? 2'b01 : 2'b11));

  assign res = addr[1] ? (addr[1] ? d : c) : (addr[0] ? b : a);

endmodule


